But what is this git_odb_backend_mine thing? Well, that’s the constructor for your own ODB
implementation, and you can do whatever you want in there, so long as you fill in the
git_odb_backend structure properly. Here’s what it could look like:
typedef struct {
    git_odb_backend parent;
    // Some other stuff
    void *custom_context;
} my_backend_struct;
int git_odb_backend_mine(git_odb_backend **backend_out, /*…*/)
{
    my_backend_struct *backend;
    backend = calloc(1, sizeof (my_backend_struct));
    backend->custom_context = …;
    backend->parent.read = &my_backend__read;

_odb_backend **backend_out, /*…*/)
{
    my_backend_struct *backend;
    backend = calloc(1, sizeof (my_backend_struct));
    backend->custom_context = …;
    backend->parent.read = &my_backend__read;
    backend->parent.read_prefix = &my_backend__read_prefix;
    backend->parent.read_header = &my_backend__read_header;
// …
    *backend_out = (git_odb_backend *) backend;
    return GIT_SUCCESS;
}
The subtlest constraint here is that my_backend_struct’s first member must be a git_odb_backend
structure; this ensures that the memory layout is what the Libgit2 code expects it to be. The rest of
it is arbitrary; this structure can be as large or small as you need it to be.
